const searchSupportTickets = `-- name: SearchSupportTickets :many

SELECT
  t.id, t.user_id, t.status, t.created_at, t.updated_at, t.subject, t.priority, t.last_message_at, t.customer_unread_count, t.closed_at, t.queue_id, t.assignee_id, t.assigned_at, t.first_response_at, t.resolved_at, t.reopened_count, t.operator_unread_count, t.merged_into_ticket_id,
  q.code AS queue_code,
  q.first_response_target_seconds,
  q.resolution_target_seconds,
  COALESCE(a.display_name, '') AS assignee_name,
  u.status AS customer_status,
  (q.first_response_target_seconds > 0
    AND t.first_response_at IS NULL
    AND t.created_at < now() - make_interval(secs => q.first_response_target_seconds))
    AS first_response_breached,
  (SELECT count(*)::bigint FROM support_messages m WHERE m.ticket_id = t.id) AS message_count,
  ARRAY(
    SELECT g.code FROM support_ticket_tags tt
    JOIN support_tags g ON g.id = tt.tag_id
    WHERE tt.ticket_id = t.id
    ORDER BY g.code
  )::text[] AS tags
FROM support_tickets t
JOIN support_queues q ON q.id = t.queue_id
JOIN users u ON u.id = t.user_id
LEFT JOIN admin_users a ON a.id = t.assignee_id
WHERE ($1::uuid IS NULL OR t.queue_id = $1::uuid)
  AND ($2::text IS NULL OR t.status = $2::text)
  AND ($3::text IS NULL OR t.priority = $3::text)
  AND ($4::uuid IS NULL OR t.assignee_id = $4::uuid)
  AND (NOT $5::boolean OR t.assignee_id IS NULL)
  AND ($6::uuid IS NULL OR t.user_id = $6::uuid)
  AND ($7::text IS NULL OR EXISTS (
    SELECT 1 FROM support_ticket_tags tt
    JOIN support_tags g ON g.id = tt.tag_id
    WHERE tt.ticket_id = t.id AND g.code = $7::text
  ))
  AND (
    $8::timestamptz IS NULL
    OR (t.last_message_at, t.id) > ($8::timestamptz, $9::uuid)
  )
ORDER BY t.last_message_at, t.id
LIMIT $10
`

type SearchSupportTicketsParams struct {
	QueueID             pgtype.UUID        `json:"queue_id"`
	Status              pgtype.Text        `json:"status"`
	Priority            pgtype.Text        `json:"priority"`
	AssigneeID          pgtype.UUID        `json:"assignee_id"`
	UnassignedOnly      bool               `json:"unassigned_only"`
	CustomerID          pgtype.UUID        `json:"customer_id"`
	Tag                 pgtype.Text        `json:"tag"`
	CursorLastMessageAt pgtype.Timestamptz `json:"cursor_last_message_at"`
	CursorID            pgtype.UUID        `json:"cursor_id"`
	PageSize            int32              `json:"page_size"`
}

type SearchSupportTicketsRow struct {
	SupportTicket              SupportTicket `json:"support_ticket"`
	QueueCode                  string        `json:"queue_code"`
	FirstResponseTargetSeconds int64         `json:"first_response_target_seconds"`
	ResolutionTargetSeconds    int64         `json:"resolution_target_seconds"`
	AssigneeName               string        `json:"assignee_name"`
	CustomerStatus             string        `json:"customer_status"`
	FirstResponseBreached      pgtype.Bool   `json:"first_response_breached"`
	MessageCount               int64         `json:"message_count"`
	Tags                       []string      `json:"tags"`
}

// ---------------------------------------------------------------------------
// Ticket queue view
// ---------------------------------------------------------------------------
// The queue. Oldest activity first, because a desk works the top of the list.
//
// The SLA columns are computed here rather than in the panel so that "overdue"
// means the same thing in the list, in the counters, and in the report.
func (q *Queries) SearchSupportTickets(ctx context.Context, arg SearchSupportTicketsParams) ([]SearchSupportTicketsRow, error) {
	rows, err := q.db.Query(ctx, searchSupportTickets,
		arg.QueueID,
		arg.Status,
		arg.Priority,
		arg.AssigneeID,
		arg.UnassignedOnly,
		arg.CustomerID,
		arg.Tag,
		arg.CursorLastMessageAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchSupportTicketsRow{}
	for rows.Next() {
		var i SearchSupportTicketsRow
		if err := rows.Scan(
			&i.SupportTicket.ID,
			&i.SupportTicket.UserID,
			&i.SupportTicket.Status,
			&i.SupportTicket.CreatedAt,
			&i.SupportTicket.UpdatedAt,
			&i.SupportTicket.Subject,
			&i.SupportTicket.Priority,
			&i.SupportTicket.LastMessageAt,
			&i.SupportTicket.CustomerUnreadCount,
			&i.SupportTicket.ClosedAt,
			&i.SupportTicket.QueueID,
			&i.SupportTicket.AssigneeID,
			&i.SupportTicket.AssignedAt,
			&i.SupportTicket.FirstResponseAt,
			&i.SupportTicket.ResolvedAt,
			&i.SupportTicket.ReopenedCount,
			&i.SupportTicket.OperatorUnreadCount,
			&i.SupportTicket.MergedIntoTicketID,
			&i.QueueCode,
			&i.FirstResponseTargetSeconds,
			&i.ResolutionTargetSeconds,
			&i.AssigneeName,
			&i.CustomerStatus,
			&i.FirstResponseBreached,
			&i.MessageCount,
			&i.Tags,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

